insert into skill_test_questions
  (id, template_id, question_text, choices, correct_index, points, order_index)
values
  ('3d70db45-34c7-5674-b6af-d8285865bb33', '4e340373-1448-4da9-9d55-e77d6af8ec3b', 'Which keyword declares a variable that can be reassigned later?', ARRAY['let', 'const', 'final', 'static'], 0, 1, 1),
  ('cd2a5eef-c752-5ef3-8916-a536cf171820', '4e340373-1448-4da9-9d55-e77d6af8ec3b', 'What does `"5" + 3` evaluate to?', ARRAY['8', '"8"', 'NaN', '"53"'], 3, 1, 2),
  ('3f3a4963-4da8-5bae-8f75-0f54415bbea1', '4e340373-1448-4da9-9d55-e77d6af8ec3b', 'What does `"5" - 3` evaluate to?', ARRAY['"53"', '2', '"2"', 'NaN'], 1, 1, 3),
  ('e01c0e48-ef59-5d08-be11-ce729f43e85d', '4e340373-1448-4da9-9d55-e77d6af8ec3b', 'What is the index of the first element in a JavaScript array?', ARRAY['1', '0', '-1', 'It depends on the array''s length'], 1, 1, 4),
  ('0a1a832b-ce58-598e-ba0c-f740a01e6c92', '4e340373-1448-4da9-9d55-e77d6af8ec3b', 'Given `const colors = ["red", "green", "blue"];`, what does `colors.length` return?', ARRAY['3', '2', '4', 'undefined'], 0, 1, 5),
  ('2e9d7dc1-b718-5502-a616-0482ab785219', '4e340373-1448-4da9-9d55-e77d6af8ec3b', 'What does `typeof "hello"` return?', ARRAY['"text"', '"object"', '"char"', '"string"'], 3, 1, 6),
  ('108ab7dd-99b8-558b-b35e-f3b9435f54d3', '4e340373-1448-4da9-9d55-e77d6af8ec3b', 'Which of these is a single-line comment in JavaScript?', ARRAY['// comment', '# comment', '-- comment', ''' comment'], 0, 1, 7),
  ('2054a4c2-7e99-5688-b6e1-c80ec72c40c0', '4e340373-1448-4da9-9d55-e77d6af8ec3b', 'What does `10 % 3` evaluate to?', ARRAY['3', '3.33', '1', '0'], 2, 1, 8),
  ('389dcdb7-e74d-53a2-910c-dda99895982d', '4e340373-1448-4da9-9d55-e77d6af8ec3b', 'What does `console.log(2 === "2")` print?', ARRAY['true', 'undefined', 'false', 'It throws a TypeError'], 2, 1, 9),
  ('a0766d7f-cc61-5e8d-be9d-8ec902201127', '4e340373-1448-4da9-9d55-e77d6af8ec3b', 'What happens when this runs: `const x = 1; x = 2;`?', ARRAY['x silently stays 1', 'A TypeError is thrown', 'x becomes 2', 'x becomes undefined'], 1, 1, 10),
  ('5d073473-2967-5a85-a634-5897279d4b03', '0fa109a7-80dc-4a14-a6d3-456c4f3434a0', 'Given `function add(a, b) { return a + b; }`, what does `add(2, 3)` return?', ARRAY['"23"', 'undefined', '23', '5'], 3, 1, 1),
  ('a65f85fc-21de-5b0d-ad23-1980c20ad4c0', '0fa109a7-80dc-4a14-a6d3-456c4f3434a0', 'What does a function return if it has no `return` statement?', ARRAY['null', 'undefined', '0', 'An empty string'], 1, 1, 2),
  ('d072bae8-6a29-54fe-9450-f5464b1b176f', '0fa109a7-80dc-4a14-a6d3-456c4f3434a0', 'Which array method adds an element to the end of an array?', ARRAY['pop', 'shift', 'push', 'unshift'], 2, 1, 3),
  ('7e130b07-64e8-53b7-90b5-58ca19194560', '0fa109a7-80dc-4a14-a6d3-456c4f3434a0', 'What does `[1, 2, 3].includes(2)` return?', ARRAY['1', 'true', 'false', '2'], 1, 1, 4),
  ('cd47c3cb-e722-5e35-9a90-b0991fa3c3eb', '0fa109a7-80dc-4a14-a6d3-456c4f3434a0', 'Given `const user = { name: "Ana", age: 30 };`, which expression reads the name?', ARRAY['user.name', 'user->name', 'user::name', 'user[name] (without quotes)'], 0, 1, 5),
  ('12860b39-d566-5e49-9bd0-771100d8da13', '0fa109a7-80dc-4a14-a6d3-456c4f3434a0', 'What does the template literal `Total: ${2 + 3}` (written with backticks) evaluate to?', ARRAY['"Total: ${2 + 3}"', '"Total: 2 + 3"', '"Total: 23"', '"Total: 5"'], 3, 1, 6),
  ('bfb89e42-3f43-5e4b-a8ef-66a480d84c8b', '0fa109a7-80dc-4a14-a6d3-456c4f3434a0', 'Which loop iterates directly over an array''s values rather than its indexes?', ARRAY['for...of', 'for...in', 'for...each', 'do...in'], 0, 1, 7),
  ('2cadde70-0305-5f76-9538-c260707a9174', '0fa109a7-80dc-4a14-a6d3-456c4f3434a0', 'Which of these values is falsy?', ARRAY['"0"', '0', '[]', '{}'], 1, 1, 8),
  ('640f0795-7153-53ba-bd2f-32f1e62d8a9b', '0fa109a7-80dc-4a14-a6d3-456c4f3434a0', 'What does `[10, 20, 30].indexOf(40)` return?', ARRAY['undefined', 'null', '-1', '3'], 2, 1, 9),
  ('5ffa9126-4e16-5da7-973b-02a811259c29', '0fa109a7-80dc-4a14-a6d3-456c4f3434a0', 'After `const nums = [1, 2, 3]; nums.pop();`, what is `nums`?', ARRAY['[1, 2]', '[2, 3]', '[1, 2, 3]', '[3]'], 0, 1, 10),
  ('8348d242-14db-5788-83fe-556514f14cee', 'c11f6b8b-9c3d-4286-841d-50804c328f98', 'What does `[1, 2, 3].map(n => n * 2)` return?', ARRAY['[1, 2, 3]', '12', '[2, 4, 6]', 'undefined'], 2, 1, 1),
  ('7c2b2061-505b-5d6c-9901-c9edba8fa8c7', 'c11f6b8b-9c3d-4286-841d-50804c328f98', 'What does `[5, 12, 8, 130].find(n => n > 10)` return?', ARRAY['12', '[12, 130]', 'true', '1'], 0, 1, 2),
  ('24d123f8-cee3-5406-b2d2-feb140fefea5', 'c11f6b8b-9c3d-4286-841d-50804c328f98', 'What does `[1, 2, 3, 4].filter(n => n % 2 === 0)` return?', ARRAY['[1, 3]', 'true', '2', '[2, 4]'], 3, 1, 3),
  ('ea2b6030-42b5-5284-bfa2-2db34b669560', 'c11f6b8b-9c3d-4286-841d-50804c328f98', 'After `const [first, , third] = ["a", "b", "c"];`, what is `third`?', ARRAY['"c"', '"b"', 'undefined', '["c"]'], 0, 1, 4),
  ('45335bc4-a53c-5406-a70d-ab67527f9c1c', 'c11f6b8b-9c3d-4286-841d-50804c328f98', 'After `const { name, role = "dev" } = { name: "Sam" };`, what is `role`?', ARRAY['undefined', '"dev"', 'null', 'A ReferenceError is thrown'], 1, 1, 5),
  ('998dcf76-1a30-53fd-9e5d-7fd9912e17c1', 'c11f6b8b-9c3d-4286-841d-50804c328f98', 'What does `"hello world".split(" ")` return?', ARRAY['["hello world"]', '["hello", " ", "world"]', '"hello,world"', '["hello", "world"]'], 3, 1, 6),
  ('0eee2d0a-d96b-5704-820d-07071445f402', 'c11f6b8b-9c3d-4286-841d-50804c328f98', 'What does `"JavaScript".slice(0, 4)` return?', ARRAY['"Javas"', '"Java"', '"avaS"', '"Jav"'], 1, 1, 7),
  ('b67477fc-9954-5e61-a704-d481bd06fd61', 'c11f6b8b-9c3d-4286-841d-50804c328f98', 'What does this print: `if (true) { let x = 1; } console.log(typeof x);`?', ARRAY['"number"', '1', '"undefined"', 'A ReferenceError is thrown'], 2, 1, 8),
  ('a8c94bcc-dbad-5dec-b385-61946d391aed', 'c11f6b8b-9c3d-4286-841d-50804c328f98', 'What does this print: `if (true) { var y = 1; } console.log(y);`?', ARRAY['undefined', 'A ReferenceError is thrown', 'null', '1'], 3, 1, 9),
  ('cf6ac4ac-e6f3-5b8a-8fa5-5f26c5e74e86', 'c11f6b8b-9c3d-4286-841d-50804c328f98', 'Given `function greet(name = "friend") { return "Hi " + name; }`, what does `greet()` return?', ARRAY['"Hi friend"', '"Hi undefined"', '"Hi "', 'A TypeError is thrown'], 0, 1, 10),
  ('35f704b1-cd55-5c92-9544-965dbd93d77c', 'c11f6b8b-9c3d-4286-841d-50804c328f98', 'What does `{ ...{ a: 1, b: 2 }, ...{ b: 3 } }` produce?', ARRAY['{ a: 1, b: 2 }', '{ a: 1, b: 2, b: 3 }', '{ a: 1, b: 3 }', '[{ a: 1, b: 2 }, { b: 3 }]'], 2, 1, 11),
  ('aa5ec7ee-701e-5abb-8c0d-da5cd5e86d21', 'c11f6b8b-9c3d-4286-841d-50804c328f98', 'Given `const age = 20;`, what does `age >= 18 ? "adult" : "minor"` evaluate to?', ARRAY['"minor"', '"adult"', 'true', '18'], 1, 1, 12),
  ('ed44d949-4b35-5d55-b7e4-1e9443a34d1b', '3d086fcc-194a-4fbb-8557-a769abc72783', 'What does `[10, 1, 5, 100].sort()` return?', ARRAY['[1, 5, 10, 100]', '[100, 10, 5, 1]', '[1, 10, 100, 5]', '[10, 1, 5, 100]'], 2, 1, 1),
  ('f41254f2-49ae-5146-a9ff-bf9dc5b1afbe', '3d086fcc-194a-4fbb-8557-a769abc72783', 'Which comparator makes `.sort()` order numbers from smallest to largest?', ARRAY['(a, b) => b - a', '(a, b) => a - b', '(a, b) => a > b', '(a, b) => a + b'], 1, 1, 2),
  ('8214438c-8c8c-5d40-96cc-7f67ac03be56', '3d086fcc-194a-4fbb-8557-a769abc72783', 'What does `[1, 2, 3, 4].reduce((sum, n) => sum + n, 0)` return?', ARRAY['[1, 3, 6, 10]', '10', '"1234"', '24'], 1, 1, 3),
  ('5a679dc5-65f6-5d55-8165-318f9bf90bb4', '3d086fcc-194a-4fbb-8557-a769abc72783', 'What happens when you call `[].reduce((a, b) => a + b)` with no initial value?', ARRAY['It returns 0', 'It returns undefined', 'It returns an empty array', 'A TypeError is thrown'], 3, 1, 4),
  ('5c06c5e3-9b2b-5d2e-8e1e-43b84a44322b', '3d086fcc-194a-4fbb-8557-a769abc72783', 'Given `function counter() { let n = 0; return () => ++n; } const c = counter(); c(); c();`, what does the next `c()` return?', ARRAY['1', '3', '0', 'NaN'], 1, 1, 5),
  ('05dcc1d4-0036-563c-9fa5-62a976e569f6', '3d086fcc-194a-4fbb-8557-a769abc72783', 'After `const a = { x: 1 }; const b = a; b.x = 2;`, what is `a.x`?', ARRAY['1', 'undefined', 'A TypeError is thrown because a is const', '2'], 3, 1, 6),
  ('f7a82e54-0b1d-5790-aa76-d73bde49a1a1', '3d086fcc-194a-4fbb-8557-a769abc72783', 'After `const original = { info: { score: 1 } }; const copy = { ...original }; copy.info.score = 99;`, what is `original.info.score`?', ARRAY['1', 'undefined', '99', 'A ReferenceError is thrown'], 2, 1, 7),
  ('cfd8c436-85b2-5ba6-a1dd-7d43e5395676', '3d086fcc-194a-4fbb-8557-a769abc72783', 'If `user` is `{}`, what does `user?.address?.city` evaluate to?', ARRAY['null', 'A TypeError is thrown', 'undefined', '""'], 2, 1, 8),
  ('3e0371c4-3ad8-5d77-908a-34cafdd2b034', '3d086fcc-194a-4fbb-8557-a769abc72783', 'What does `("" ?? "default") + "|" + ("" || "default")` evaluate to?', ARRAY['"|default"', '"default|default"', '"|"', '"default|"'], 0, 1, 9),
  ('e6232f07-bd9c-5b81-91a7-e607790e7c1a', '3d086fcc-194a-4fbb-8557-a769abc72783', 'Given `function f(first, ...rest) { return rest.length; }`, what does `f(1, 2, 3, 4)` return?', ARRAY['3', '4', '1', '[2, 3, 4]'], 0, 1, 10),
  ('7880d3aa-3854-50a8-bc0e-7e10019527e9', '3d086fcc-194a-4fbb-8557-a769abc72783', 'What does `JSON.stringify({ a: undefined, b: () => 1, c: null })` return?', ARRAY['''{"c":null}''', '''{"a":undefined,"b":"() => 1","c":null}''', '''{"a":null,"b":null,"c":null}''', '''{}'''], 0, 1, 11),
  ('00ad518a-b8dc-520c-939a-2fad31f790a5', '3d086fcc-194a-4fbb-8557-a769abc72783', 'Which statement about `const arr = [1, 2]; arr.push(3);` is true?', ARRAY['It throws a TypeError', 'It silently does nothing', 'It creates a new array and leaves arr unchanged', 'It works: const stops reassigning the variable, not changing the array'], 3, 1, 12),
  ('c5aa67e1-6a8a-5ccf-879e-994b3ea5f51e', '1f515ffd-3ad0-47e7-998e-f9360aa6ffb1', 'What does an `async` function always return?', ARRAY['Its return value directly', 'A Promise', 'undefined until it is awaited', 'A generator object'], 1, 1, 1),
  ('7d2c97e0-49ee-54da-9322-6898ff9977d8', '1f515ffd-3ad0-47e7-998e-f9360aa6ffb1', 'What order is logged by `console.log(1); setTimeout(() => console.log(2), 0); console.log(3);`?', ARRAY['1, 2, 3', '3, 1, 2', '1, 3, 2', '2, 1, 3'], 2, 1, 2),
  ('cd493f38-1497-5582-b16e-aefd292a754d', '1f515ffd-3ad0-47e7-998e-f9360aa6ffb1', 'Which method waits for every promise to settle and never rejects just because one input rejected?', ARRAY['Promise.allSettled', 'Promise.all', 'Promise.race', 'Promise.any'], 0, 1, 3),
  ('a4508912-9016-5bc5-af63-1618d1892256', '1f515ffd-3ad0-47e7-998e-f9360aa6ffb1', 'When does the promise returned by `Promise.any(promises)` reject?', ARRAY['Only when every input rejects, with an AggregateError', 'As soon as any input rejects', 'Never', 'When the first input settles, either way'], 0, 1, 4),
  ('a261b132-a3e9-5f26-836c-7689bea968a6', '1f515ffd-3ad0-47e7-998e-f9360aa6ffb1', 'In `Promise.race([slow, fast])`, if `fast` rejects before `slow` resolves, what does the race do?', ARRAY['Resolves with slow''s value', 'Rejects with fast''s error', 'Waits for both to settle', 'Resolves with undefined'], 1, 1, 5),
  ('cd0e5763-9bd1-5919-b875-21a3e9fa09d9', '1f515ffd-3ad0-47e7-998e-f9360aa6ffb1', 'What is logged by `async function f() { throw new Error("x"); } f().catch(e => console.log(e.message));`?', ARRAY['Nothing — the error crashes the program', 'undefined', 'Error: x is thrown synchronously when f() is called', 'x'], 3, 1, 6),
  ('5695e9a3-b9c8-5f99-ba82-18805f745170', '1f515ffd-3ad0-47e7-998e-f9360aa6ffb1', 'Inside an async function, what does `try { await Promise.reject(new Error("boom")); } catch (e) { return "caught"; }` resolve to?', ARRAY['It rejects with the "boom" error', '"caught"', 'undefined', '"boom"'], 1, 1, 7),
  ('b6367205-52a6-5d3d-b48c-24654ec31870', '1f515ffd-3ad0-47e7-998e-f9360aa6ffb1', 'With `const wait = ms => new Promise(r => setTimeout(r, ms));`, about how long does `await Promise.all([wait(100), wait(100)])` take?', ARRAY['About 200 ms', '0 ms', 'It never resolves', 'About 100 ms'], 3, 1, 8),
  ('16783623-7e26-5a58-8e6f-c184c2c5d270', '1f515ffd-3ad0-47e7-998e-f9360aa6ffb1', 'What does `await 5` evaluate to inside an async function?', ARRAY['A TypeError, because 5 is not a promise', 'undefined', '5, after a microtask tick', 'A Promise that resolves to 5'], 2, 1, 9),
  ('713b9212-d83b-5903-825b-904d451dc52b', '1f515ffd-3ad0-47e7-998e-f9360aa6ffb1', 'What does `new Promise(resolve => { resolve("a"); resolve("b"); }).then(console.log)` log?', ARRAY['a', 'b', 'a, then b', 'An error, because the promise was already resolved'], 0, 1, 10),
  ('32b00c27-e75b-5303-bc04-9fbfe98d2a05', '1f515ffd-3ad0-47e7-998e-f9360aa6ffb1', 'What order is logged by `queueMicrotask(() => console.log("micro")); setTimeout(() => console.log("macro")); console.log("sync");`?', ARRAY['sync, micro, macro', 'sync, macro, micro', 'micro, sync, macro', 'macro, micro, sync'], 0, 1, 11),
  ('43103b17-e1b3-51c5-8814-b15ac3eab3bd', '1f515ffd-3ad0-47e7-998e-f9360aa6ffb1', 'In strict mode, given `const obj = { n: 1, get() { return this.n; } }; const fn = obj.get;`, what happens when you call `fn()`?', ARRAY['It returns 1', 'A TypeError is thrown, because this is undefined', 'It returns undefined', 'It returns null'], 1, 1, 12),
  ('8dd5691a-698d-5835-80ae-33018faaa102', '1f515ffd-3ad0-47e7-998e-f9360aa6ffb1', 'Given `const obj = { n: 1, get() { return this.n; } };`, which expression creates a function that always runs `get` with `this` set to `obj`?', ARRAY['obj.get.call', 'Object.assign(obj.get)', 'obj.get.bind(obj)', 'obj.get.apply'], 2, 1, 13),
  ('0d55eed3-eac7-5a2f-b620-4ca2c319a8a3', '1f515ffd-3ad0-47e7-998e-f9360aa6ffb1', 'With the Fetch API, what happens when the server responds with HTTP 404?', ARRAY['The promise rejects with a 404 error', 'fetch throws synchronously', 'fetch retries the request automatically', 'The promise resolves and response.ok is false'], 3, 1, 14),
  ('027234a5-d1b4-5b11-b824-869c34bf8bdf', '1400f0f2-89ae-47d2-b766-8863c50884e3', 'What happens when this runs: `sayHi(); function sayHi() { console.log("hi"); }`?', ARRAY['It logs "hi"', 'A ReferenceError is thrown', 'A TypeError is thrown', 'It logs undefined'], 0, 1, 1),
  ('72e43b45-c755-5ab7-a5ed-d2f2d3e4d4e2', '1400f0f2-89ae-47d2-b766-8863c50884e3', 'What happens when this runs: `sayHi(); var sayHi = function () { console.log("hi"); };`?', ARRAY['It logs "hi"', 'A ReferenceError is thrown', 'A TypeError is thrown, because sayHi is undefined at that point', 'It logs undefined'], 2, 1, 2),
  ('7e8e0647-a9da-521f-8a97-1d6130eded81', '1400f0f2-89ae-47d2-b766-8863c50884e3', 'What happens when this runs: `console.log(x); let x = 1;`?', ARRAY['It logs undefined', 'It logs 1', 'It logs null', 'A ReferenceError is thrown'], 3, 1, 3),
  ('6b9767c9-8cb2-53da-bd25-575331b74214', '1400f0f2-89ae-47d2-b766-8863c50884e3', 'Given `class A { static create() { return new A(); } }`, how do you call `create`?', ARRAY['A.create()', 'new A().create()', 'A.prototype.create()', 'create()'], 0, 1, 4),
  ('cdb83b54-b915-5241-90a5-a65e76133e83', '1400f0f2-89ae-47d2-b766-8863c50884e3', 'Given `class Account { #balance = 0; }`, what happens if code outside the class reads `new Account().#balance`?', ARRAY['It returns 0', 'A SyntaxError: private fields can''t be referenced outside their class', 'It returns undefined', 'A TypeError at runtime'], 1, 1, 5),
  ('d067d854-270c-54a8-8974-38e1a4794fa5', '1400f0f2-89ae-47d2-b766-8863c50884e3', 'What happens when you construct `class Dog extends Animal { constructor(name) { this.name = name; super(); } }` (Animal is any class)?', ARRAY['It works normally', 'A TypeError is thrown', 'It works but name is undefined', 'A ReferenceError: this can''t be used before super() is called'], 3, 1, 6),
  ('731b3a04-1976-5817-acce-97b1a8e64f05', '1400f0f2-89ae-47d2-b766-8863c50884e3', 'Given `const t = { c: 25, get f() { return this.c * 9 / 5 + 32; } };`, what is `t.f`?', ARRAY['A function', '77', 'undefined', '25'], 1, 1, 7),
  ('0169b163-c516-589e-ae33-87259b8c5bd4', '1400f0f2-89ae-47d2-b766-8863c50884e3', 'After `const cfg = Object.freeze({ db: { host: "a" } }); cfg.db.host = "b";`, what is `cfg.db.host`?', ARRAY['"a"', 'undefined', 'A TypeError is always thrown', '"b"'], 3, 1, 8),
  ('1efe8e0e-c40e-5ce5-824f-0568bc76adbc', '1400f0f2-89ae-47d2-b766-8863c50884e3', 'A module has `export default function () {}` and `export const x = 1;`. Which statement imports both?', ARRAY['import { default, x } from "./mod.js";', 'import fn, x from "./mod.js";', 'import fn, { x } from "./mod.js";', 'import * as fn, x from "./mod.js";'], 2, 1, 9),
  ('024c5a68-34f4-5150-a69d-aae44d32768c', '1400f0f2-89ae-47d2-b766-8863c50884e3', 'What does `typeof class Foo {}` return?', ARRAY['"class"', '"object"', '"function"', '"constructor"'], 2, 1, 10),
  ('6be9156d-6d37-5592-aaf3-0c8929bde85e', '1400f0f2-89ae-47d2-b766-8863c50884e3', 'Given `class P { greet() {} }`, what does `new P().greet === new P().greet` evaluate to?', ARRAY['true, because methods live on the shared prototype', 'false, because each instance gets its own copy', 'undefined', 'A TypeError is thrown'], 0, 1, 11),
  ('ef7726b0-bb0a-5d00-9ca2-d1cdfddead7c', '1400f0f2-89ae-47d2-b766-8863c50884e3', 'Given `class A {} class B extends A {}`, what does `new B() instanceof A` evaluate to?', ARRAY['true', 'false', 'undefined', 'A TypeError is thrown'], 0, 1, 12),
  ('16bd40e0-90f7-5484-b8ce-a17973b30a8a', '1400f0f2-89ae-47d2-b766-8863c50884e3', 'Given `class P { constructor() { this.a = 1; } m() {} }`, what does `Object.keys(new P())` return?', ARRAY['["a", "m"]', '["a"]', '["constructor", "a", "m"]', '[]'], 1, 1, 13),
  ('6d9466fe-997c-5914-905e-cc8f09fae054', '1400f0f2-89ae-47d2-b766-8863c50884e3', 'What does `typeof []` return, and what is the reliable way to check for an array?', ARRAY['"array" — use typeof value === "array"', '"object" — use Array.isArray(value)', '"object" — use value instanceof Object', '"list" — use Array.isList(value)'], 1, 1, 14),
  ('cb642059-3c14-578b-b3f0-0d408cd44a10', '2233f74c-fc3c-4121-a218-9aa2dd1384c9', 'What does `for (var i = 0; i < 3; i++) setTimeout(() => console.log(i));` log?', ARRAY['3, 3, 3', '0, 1, 2', 'undefined, undefined, undefined', '2, 2, 2'], 0, 1, 1),
  ('c16f8245-aee6-5eb2-9a0b-af12a52ae126', '2233f74c-fc3c-4121-a218-9aa2dd1384c9', 'Why does changing `var` to `let` in `for (var i = 0; i < 3; i++) setTimeout(() => console.log(i));` make it log 0, 1, 2?', ARRAY['let makes setTimeout run synchronously', 'let creates a new binding for each iteration, and each callback closes over its own one', 'let is hoisted to the top of the file', 'let copies i into the global scope'], 1, 1, 2),
  ('d56a9f22-7fbb-5275-a944-a830e57511f3', '2233f74c-fc3c-4121-a218-9aa2dd1384c9', 'What order is logged by `async function a() { console.log(1); await null; console.log(2); } a(); console.log(3);`?', ARRAY['1, 3, 2', '1, 2, 3', '3, 1, 2', '1, 3 (2 is never logged)'], 0, 1, 3),
  ('c927eaef-bf55-535c-a347-3aa5c04a98d1', '2233f74c-fc3c-4121-a218-9aa2dd1384c9', 'What order is logged by `setTimeout(() => console.log("t")); Promise.resolve().then(() => { console.log("p1"); Promise.resolve().then(() => console.log("p2")); }); console.log("s");`?', ARRAY['s, p1, t, p2', 's, p1, p2, t', 's, t, p1, p2', 'p1, p2, s, t'], 1, 1, 4),
  ('84d79b03-b492-57c8-b1ad-f1e4cf37f98e', '2233f74c-fc3c-4121-a218-9aa2dd1384c9', 'Given `function* g() { yield 1; yield 2; } const it = g(); it.next(); it.next();`, what does a third `it.next()` return?', ARRAY['{ value: undefined, done: true }', '{ value: 2, done: true }', '{ value: undefined, done: false }', 'It throws an error'], 0, 1, 5),
  ('b9dfff33-08ea-53a8-bd6c-7f435cca86b6', '2233f74c-fc3c-4121-a218-9aa2dd1384c9', 'Given `function* g() { yield 1; yield 2; return 3; }`, what is `[...g()]`?', ARRAY['[1, 2, 3]', '[3]', '[]', '[1, 2]'], 3, 1, 6),
  ('6f2db77d-3f12-5698-9cad-21ed8256a659', '2233f74c-fc3c-4121-a218-9aa2dd1384c9', 'What must an object implement to be usable in a `for...of` loop?', ARRAY['A length property and numeric keys', 'A [Symbol.iterator]() method that returns an iterator', 'A forEach method', 'Only a next() method on the object itself'], 1, 1, 7),
  ('624de75b-987a-5043-9bef-cab5c860792f', '2233f74c-fc3c-4121-a218-9aa2dd1384c9', 'After `const m = new Map(); m.set(1, "a"); m.set("1", "b");`, what is `m.size`?', ARRAY['1', '0', '2', 'A TypeError is thrown'], 2, 1, 8),
  ('069499ef-584f-536b-b1df-ec4e23b6ce2f', '2233f74c-fc3c-4121-a218-9aa2dd1384c9', 'After `const o = {}; o[1] = "a"; o["1"] = "b";`, what is `Object.keys(o).length`?', ARRAY['2', '0', 'A TypeError is thrown', '1, because object keys are converted to strings'], 3, 1, 9),
  ('9caafef8-517c-5045-8f2b-2859825fe7f5', '2233f74c-fc3c-4121-a218-9aa2dd1384c9', 'What is a WeakMap best suited for?', ARRAY['Storing primitive keys efficiently', 'Iterating keys in insertion order', 'Attaching data to objects without stopping them from being garbage-collected', 'Sharing a cache across processes'], 2, 1, 10),
  ('05c254ca-ee39-5418-92cc-0f2a2e8aca70', '2233f74c-fc3c-4121-a218-9aa2dd1384c9', 'What does debouncing a function do?', ARRAY['Calls it at most once per interval, however often it''s triggered', 'Cancels every call after the first', 'Delays calling it until a set time has passed since the last call', 'Runs it on the next animation frame'], 2, 1, 11),
  ('8e4a3b75-1947-55f5-8de5-ae1c0c03f4e5', '2233f74c-fc3c-4121-a218-9aa2dd1384c9', 'Given `const add = a => b => c => a + b + c;`, what does `add(1)(2)(3)` return?', ARRAY['A function', 'NaN', '6', '"123"'], 2, 1, 12),
  ('17cf38ca-a7c0-5a20-88ea-6f039c314070', '2233f74c-fc3c-4121-a218-9aa2dd1384c9', 'What does `[[1], [2, [3]]].flat()` return?', ARRAY['[1, 2, [3]]', '[1, 2, 3]', '[[1], [2, [3]]]', '[1, [2, [3]]]'], 0, 1, 13),
  ('e9e2e382-d294-502d-82cd-2f6be37a046f', '2233f74c-fc3c-4121-a218-9aa2dd1384c9', 'Given `const counter = (() => { let count = 0; return { inc: () => ++count }; })();`, what is `counter.count`?', ARRAY['0', 'undefined', '1', 'A ReferenceError is thrown'], 1, 1, 14),
  ('6281754d-2b05-53f4-bccb-740c1a859bf9', '2233f74c-fc3c-4121-a218-9aa2dd1384c9', 'What order is logged by `new Promise(() => console.log("a")); console.log("b");`?', ARRAY['b, a', 'Only b', 'Only a', 'a, b'], 3, 1, 15),
  ('eb0b0c95-e6f9-55f3-bf9c-7c290966ba1c', '2233f74c-fc3c-4121-a218-9aa2dd1384c9', 'What happens with `try { setTimeout(() => { throw new Error("x"); }); } catch { console.log("caught"); }`?', ARRAY['"caught" is logged', 'The error is silently swallowed', 'setTimeout throws immediately and it is caught', 'The error is not caught: the callback runs after the try/catch has finished'], 3, 1, 16),
  ('c587d777-4d40-514c-b3f7-75e7e29d3066', '0fd04ce0-38be-43f6-8eb4-f357be1f8019', 'What does `Object.getPrototypeOf(Object.create(null))` return?', ARRAY['null', 'Object.prototype', 'undefined', '{}'], 0, 1, 1),
  ('2d437570-c792-5aa1-a688-a571fd1e09d2', '0fd04ce0-38be-43f6-8eb4-f357be1f8019', 'Given `const o = Object.create({ hi() { return "hi " + this.name; } }); o.name = "Ana";`, what does `o.hi()` return?', ARRAY['"hi undefined"', '"hi Ana"', 'A TypeError is thrown', '"hi "'], 1, 1, 2),
  ('9e2fb817-9906-5544-8f73-1af709db9d1c', '0fd04ce0-38be-43f6-8eb4-f357be1f8019', 'Given `const o = Object.create({ hi() {} });`, what does `Object.hasOwn(o, "hi")` return?', ARRAY['true', 'undefined', 'A TypeError is thrown', 'false'], 3, 1, 3),
  ('b3bebcff-379d-5484-8194-22e648d9e3e8', '0fd04ce0-38be-43f6-8eb4-f357be1f8019', 'What does `["1", "2", "3"].map(parseInt)` return?', ARRAY['[1, 2, 3]', '["1", "2", "3"]', '[NaN, NaN, NaN]', '[1, NaN, NaN]'], 3, 1, 4),
  ('d3b118da-91df-5a73-932f-c79d625ac1e1', '0fd04ce0-38be-43f6-8eb4-f357be1f8019', 'Given `function f() { return this.v; } const g = f.bind({ v: 1 }).bind({ v: 2 });`, what does `g()` return?', ARRAY['1', '2', 'undefined', 'A TypeError is thrown'], 0, 1, 5),
  ('3aa03735-2c9a-5b05-8aeb-dcb2be9b92c2', '0fd04ce0-38be-43f6-8eb4-f357be1f8019', 'Given `function F() { this.a = 1; return { b: 2 }; }`, what is `new F().a`?', ARRAY['1', 'undefined', '2', 'A TypeError is thrown'], 1, 1, 6),
  ('648e0d16-dfa7-5a54-9513-f49c5a99b18b', '0fd04ce0-38be-43f6-8eb4-f357be1f8019', 'What does the expression `[] + {}` evaluate to?', ARRAY['0', '"{}"', '"[object Object]"', 'NaN'], 2, 1, 7),
  ('a0d4122b-20a5-5c43-9fa7-560672742d1f', '0fd04ce0-38be-43f6-8eb4-f357be1f8019', 'What does `[] == false` evaluate to?', ARRAY['false', 'A TypeError is thrown', 'true', 'undefined'], 2, 1, 8),
  ('7146ffba-973f-52bb-bd2e-a8c975100e5f', '0fd04ce0-38be-43f6-8eb4-f357be1f8019', 'What does `0.1 + 0.2 === 0.3` evaluate to?', ARRAY['false, because 0.1 + 0.2 is 0.30000000000000004', 'true', 'false, because 0.1 + 0.2 is NaN', 'A RangeError is thrown'], 0, 1, 9),
  ('d6eed049-b20b-59dd-ae2a-ed6c5e1477d5', '0fd04ce0-38be-43f6-8eb4-f357be1f8019', 'What do `Object.is(NaN, NaN)` and `NaN === NaN` evaluate to?', ARRAY['false and false', 'true and true', 'true and false', 'false and true'], 2, 1, 10),
  ('847c0cef-0112-5b02-9712-0c1089479270', '0fd04ce0-38be-43f6-8eb4-f357be1f8019', 'What does `[0 === -0, Object.is(0, -0)]` evaluate to?', ARRAY['[true, true]', '[true, false]', '[false, false]', '[false, true]'], 1, 1, 11),
  ('1f9c073c-0623-5575-ac0a-29f0560466de', '0fd04ce0-38be-43f6-8eb4-f357be1f8019', 'What happens when you evaluate `10n + 5`?', ARRAY['15n', '15', '"105"', 'A TypeError: BigInt and Number can''t be mixed'], 3, 1, 12),
  ('568e9008-4241-54fa-b543-3028f9c87d60', '0fd04ce0-38be-43f6-8eb4-f357be1f8019', 'Given `const tag = (strings, ...vals) => strings.length + vals.length;`, what does tag`a${1}b${2}c` (a tagged template) return?', ARRAY['3', '5', '2', '6'], 1, 1, 13),
  ('e651915f-589e-568b-a7da-5d30da570a66', '0fd04ce0-38be-43f6-8eb4-f357be1f8019', 'Given `const p = new Proxy({}, { get: (t, k) => (k in t ? t[k] : "missing") });`, what is `p.foo`?', ARRAY['undefined', 'A TypeError is thrown', '"missing"', '"foo"'], 2, 1, 14),
  ('52488e81-3ff8-5219-be39-bf73ece73070', '0fd04ce0-38be-43f6-8eb4-f357be1f8019', 'What does `Reflect.ownKeys(obj)` return?', ARRAY['The same as Object.keys(obj)', 'Only symbol keys', 'Own and inherited enumerable keys', 'All own keys, including non-enumerable and symbol keys'], 3, 1, 15),
  ('0c7b6260-9ee1-5917-9ad2-ce0504566c96', '0fd04ce0-38be-43f6-8eb4-f357be1f8019', 'What does `parseInt(0.0000005)` return?', ARRAY['5', '0', 'NaN', '5e-7'], 0, 1, 16),
  ('05ec4360-2b08-5376-8eda-cb01e2266215', 'ca84c036-9abd-4ef5-85d1-3a9ce7ddb775', 'In non-strict code, after `const o = {}; Object.defineProperty(o, "x", { value: 1 }); o.x = 2;`, what is `o.x`?', ARRAY['1, because the property is not writable by default', '2', 'undefined', 'A TypeError is always thrown'], 0, 1, 1),
  ('f100ad5c-538b-56b8-8959-694f15cf02d7', 'ca84c036-9abd-4ef5-85d1-3a9ce7ddb775', 'In strict mode, what does `o.x = 2` do after `Object.defineProperty(o, "x", { value: 1 })`?', ARRAY['Is silently ignored', 'Throws a TypeError', 'Sets o.x to 2', 'Defines a second x property'], 1, 1, 2),
  ('4ae83d74-ec79-57fc-8613-720c3fb40d7b', 'ca84c036-9abd-4ef5-85d1-3a9ce7ddb775', 'Given `const money = { [Symbol.toPrimitive](hint) { return hint === "number" ? 42 : "forty-two"; } };`, what do the template literal `${money}` and `+money` evaluate to?', ARRAY['42 and 42', '"forty-two" and NaN', '"[object Object]" and NaN', '"forty-two" and 42'], 3, 1, 3),
  ('b1e18596-c524-5617-b391-56e3fc5d651d', 'ca84c036-9abd-4ef5-85d1-3a9ce7ddb775', 'Given `const a = { d: new Date(0), m: new Map([[1, 2]]) }; const b = structuredClone(a);`, which is true?', ARRAY['b.d is a string and b.m is an empty object, as with JSON', 'It throws, because Map can''t be cloned', 'b.d and b.m are the same objects as a.d and a.m', 'b.d is a Date and b.m is a Map, both new copies'], 3, 1, 4),
  ('d98cf04e-733f-5f85-a022-875cb529ce68', 'ca84c036-9abd-4ef5-85d1-3a9ce7ddb775', 'What does `structuredClone({ f() {} })` do?', ARRAY['Copies the function', 'Silently drops f and returns {}', 'Returns the same object', 'Throws a DataCloneError, because functions can''t be cloned'], 3, 1, 5),
  ('5fb3ee96-d5de-5335-9b5f-ead5755bfab3', 'ca84c036-9abd-4ef5-85d1-3a9ce7ddb775', 'Given `async function* gen() { yield 1; yield 2; }`, how do you consume it inside an async function?', ARRAY['for (const x of gen()) { ... }', 'gen().forEach(x => { ... })', 'for await (const x of gen()) { ... }', 'await gen().all()'], 2, 1, 6),
  ('480cfe6c-a13d-567f-8a72-c453c5e5b6e2', 'ca84c036-9abd-4ef5-85d1-3a9ce7ddb775', 'After `const ac = new AbortController(); const p = fetch(url, { signal: ac.signal }); ac.abort();`, what happens to `p`?', ARRAY['It resolves with a partial response', 'It rejects with an AbortError', 'Nothing — abort() only works before fetch is called', 'abort() throws synchronously'], 1, 1, 7),
  ('d411e4d6-cecb-5312-8fbe-358d6568f235', 'ca84c036-9abd-4ef5-85d1-3a9ce7ddb775', 'counter.js has `export let count = 0; export function inc() { count++; }`. If main.js runs `import { count, inc } from "./counter.js"; inc(); console.log(count);`, what is logged?', ARRAY['0, because imports are copies', 'A ReferenceError is thrown', '1, because imports are live bindings', 'undefined'], 2, 1, 8),
  ('1093c50c-02d6-58eb-bd2b-b3022749aea5', 'ca84c036-9abd-4ef5-85d1-3a9ce7ddb775', 'What happens when a module runs `import { count } from "./counter.js"; count = 5;`?', ARRAY['A TypeError, because imported bindings are read-only', 'count becomes 5 in both modules', 'count becomes 5 only in the importing module', 'It is silently ignored'], 0, 1, 9),
  ('3dcc2385-e4c3-56f6-b471-cf1482394859', 'ca84c036-9abd-4ef5-85d1-3a9ce7ddb775', 'Since ES2019, what does the spec require of `Array.prototype.sort`?', ARRAY['Nothing about order: equal elements may be reordered', 'It must use quicksort', 'It must be stable: equal elements keep their original order', 'It must be stable only for numeric arrays'], 2, 1, 10),
  ('067258f3-8059-5430-a5c5-936400dd09ea', 'ca84c036-9abd-4ef5-85d1-3a9ce7ddb775', 'What does `[1, , 3].map(x => x * 2)` return?', ARRAY['[2, <empty>, 6] — the hole is skipped and kept', '[2, NaN, 6]', '[2, 0, 6]', '[2, 6]'], 0, 1, 11),
  ('91bb8776-702b-5eba-bc0a-6c6778f93085', 'ca84c036-9abd-4ef5-85d1-3a9ce7ddb775', 'Given `function f() { try { return 1; } finally { return 2; } }`, what does `f()` return?', ARRAY['1', '2', 'undefined', 'A SyntaxError is thrown'], 1, 1, 12),
  ('6b7e32f3-8fdf-5370-928b-75653a99f8f7', 'ca84c036-9abd-4ef5-85d1-3a9ce7ddb775', 'What happens to `setTimeout(() => console.log("t"))` if code also runs `function loop() { Promise.resolve().then(loop); } loop();`?', ARRAY['"t" is logged after about 0 ms', '"t" is logged after the 4 ms timer clamp', '"t" is never logged: the microtask queue never empties, so timers never run', 'A RangeError: maximum call stack size exceeded'], 2, 1, 13),
  ('ba9f681c-6098-5ebd-b40e-ad188cace780', 'ca84c036-9abd-4ef5-85d1-3a9ce7ddb775', 'Given `const ref = new WeakRef(obj);`, what does `ref.deref()` return?', ARRAY['Always the object, since the WeakRef keeps it alive', 'The object, or undefined once it has been garbage-collected', 'A copy of the object', 'null once it has been garbage-collected'], 1, 1, 14),
  ('0e38fe2d-01c9-5ab5-a342-5190fb132ffc', 'ca84c036-9abd-4ef5-85d1-3a9ce7ddb775', 'In non-strict code, given `const o = Object.create({ get v() { return 1; } }); o.v = 2;`, what is `o.v`?', ARRAY['1: assigning to an inherited getter with no setter silently fails', '2: the assignment creates an own property', 'undefined', 'A TypeError is thrown'], 0, 1, 15),
  ('6f2917c5-91fa-5814-b949-8dd4fdf81320', 'ca84c036-9abd-4ef5-85d1-3a9ce7ddb775', 'What does `JSON.stringify({ toJSON() { return { a: 1 }; }, b: 2 })` return?', ARRAY['''{"b":2}''', '''{"a":1}''', '''{"a":1,"b":2}''', '''{"toJSON":{},"b":2}'''], 1, 1, 16),
  ('fddf7db3-f46c-53f9-995e-7156d4393f69', 'ca84c036-9abd-4ef5-85d1-3a9ce7ddb775', 'Given `const a = {}; a.self = a;`, what does `JSON.stringify(a)` do?', ARRAY['Returns ''{"self":{}}''', 'Returns ''{"self":"[Circular]"}''', 'Loops forever', 'Throws a TypeError about a circular structure'], 3, 1, 17),
  ('c4aba895-5b6b-57c2-97ff-d05401feb41f', 'ca84c036-9abd-4ef5-85d1-3a9ce7ddb775', 'Given `const a = {}; a.self = a;`, what does `structuredClone(a)` do?', ARRAY['Copies it, keeping the cycle: the copy''s self points to the copy', 'Throws a TypeError about a circular structure', 'Returns a copy where self points back to the original a', 'Loops forever'], 0, 1, 18)
